'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { BuildingOfficeIcon, PlusIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';
import { formatNumber, formatDate } from '@/lib/utils';

// Mock data for development
const mockBranches = [
  {
    id: '1',
    name: 'Main Branch',
    code: 'MAIN',
    address: '123 Main St, City, State 12345',
    phone: '+1 (555) 123-4567',
    email: 'main@pos.com',
    manager_id: '1',
    is_active: true,
    created_at: '2024-01-15T10:30:00Z',
    updated_at: '2024-03-10T14:20:00Z',
  },
  {
    id: '2',
    name: 'North Branch',
    code: 'NORTH',
    address: '456 North Ave, City, State 67890',
    phone: '+1 (555) 987-6543',
    email: 'north@pos.com',
    manager_id: '2',
    is_active: true,
    created_at: '2024-02-01T09:15:00Z',
    updated_at: '2024-03-05T11:30:00Z',
  },
  {
    id: '3',
    name: 'East Branch',
    code: 'EAST',
    address: '789 East Blvd, City, State 13579',
    phone: '+1 (555) 246-8135',
    email: 'east@pos.com',
    manager_id: '3',
    is_active: false,
    created_at: '2024-01-20T13:45:00Z',
    updated_at: '2024-02-28T16:45:00Z',
  },
];

export default function BranchesPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredBranches, setFilteredBranches] = useState(mockBranches);

  useEffect(() => {
    const filtered = mockBranches.filter(branch =>
      branch.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      branch.code.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredBranches(filtered);
  }, [searchTerm]);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-primary">Branches</h1>
              <p className="mt-1 text-sm text-text-secondary">
                Manage your store locations and their inventory
              </p>
            </div>
            <button className="btn-primary">
              <PlusIcon className="h-5 w-5 mr-2" />
              Add Branch
            </button>
          </div>

          {/* Search */}
          <div className="card p-4">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-5 w-5 text-text-secondary" />
              </div>
              <input
                type="text"
                placeholder="Search branches..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input-field w-full pl-10"
              />
            </div>
          </div>

          {/* Branches Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredBranches.map((branch) => (
              <div key={branch.id} className="card p-6 hover:shadow-lg transition-shadow">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-3">
                      <h3 className="text-lg font-semibold text-primary">{branch.name}</h3>
                      <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                        branch.is_active ? 'status-success' : 'status-error'
                      }`}>
                        {branch.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </div>
                    <p className="text-sm text-text-secondary mt-1">Code: {branch.code}</p>
                    <p className="text-sm text-text-secondary">{branch.address}</p>
                    <p className="text-sm text-text-secondary">{branch.phone}</p>
                  </div>
                  <div className="flex space-x-2">
                    <button className="p-2 text-primary hover:bg-primary/10 rounded-lg transition-colors">
                      <PlusIcon className="h-4 w-4" />
                    </button>
                    <button className="p-2 text-text-secondary hover:bg-surface rounded-lg transition-colors">
                      <BuildingOfficeIcon className="h-4 w-4" />
                    </button>
                  </div>
                </div>
                <div className="mt-4 pt-4 border-t border-divider">
                  <div className="flex justify-between text-xs text-text-secondary">
                    <span>Created: {formatDate(branch.created_at)}</span>
                    <span>Updated: {formatDate(branch.updated_at)}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {filteredBranches.length === 0 && (
            <div className="text-center py-12">
              <BuildingOfficeIcon className="h-12 w-12 text-text-secondary mx-auto mb-4" />
              <h3 className="text-lg font-medium text-primary mb-2">No branches found</h3>
              <p className="text-text-secondary">Try adjusting your search criteria</p>
            </div>
          )}
        </div>
      </Layout>
    </AuthGuard>
  );
}
